SELECT message_id, role, content, model, create_time
FROM ai_chat_message WHERE conversation_id=#{conversationId}
ORDER BY message_id ASC

SELECT role, content FROM (
  SELECT message_id, role, content FROM ai_chat_message
  WHERE conversation_id=#{conversationId}
  ORDER BY message_id DESC LIMIT #{limit}
) recent_messages ORDER BY message_id ASC
